const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const since = weekAgo.toISOString();
const until = now.toISOString();

return [{
  since: since,
  until: until,
  weekStart: weekAgo.toISOString().split('T')[0],
  weekEnd: now.toISOString().split('T')[0]
}];

// Get data from previous nodes
const config = $node['Set Configuration'].json;
const dates = $node['Calculate Date Range'].json;
const commits = $node['Fetch Commits'].json;
const issues = $node['Fetch Closed Issues'].json;
const prs = $node['Fetch Merged PRs'].json;

// Filter PRs that were actually merged this week
const mergedPrs = Array.isArray(prs) ? prs.filter(p => p.merged_at && new Date(p.merged_at) >= new Date(dates.since)) : [];
const closedIssues = Array.isArray(issues) ? issues.filter(i => i.closed_at && new Date(i.closed_at) >= new Date(dates.since) && !i.pull_request) : [];

// Build a structured summary for Claude
const language = config.language || 'EN';

const prompt = language === 'EN' 
  ? `Generate a weekly development summary for the repository '${config.repo}'.

Week: ${dates.weekStart} to ${dates.weekEnd}

## Commits (${Array.isArray(commits) ? commits.length : 0})
${(Array.isArray(commits) ? commits.slice(0, 30).map(c => `- ${c.commit.message.split('\n')[0]} (${c.author?.login || 'unknown'})`) : ['- No data']).join('\n')}

## Merged Pull Requests (${mergedPrs.length})
${(mergedPrs.length > 0 ? mergedPrs.map(pr => `- #${pr.number} ${pr.title} (${pr.user?.login})`) : ['- No PRs merged this week']).join('\n')}

## Closed Issues (${closedIssues.length})
${(closedIssues.length > 0 ? closedIssues.map(issue => `- #${issue.number} ${issue.title}`) : ['- No issues closed this week']).join('\n')}

## Format
Write a narrative summary with these sections:
1. **Highlights** (top 2-3 achievements this week)
2. **Code Changes** (major areas of work)
3. **Issues & Fixes** (bugs fixed, challenges addressed)
4. **Looking Ahead** (what to watch next week)

Keep it concise and informative. Use Markdown.`
  : `为仓库 '${config.repo}' 生成周报。

周: ${dates.weekStart} 到 ${dates.weekEnd}

## 提交 (${Array.isArray(commits) ? commits.length : 0})
${(Array.isArray(commits) ? commits.slice(0, 30).map(c => `- ${c.commit.message.split('\n')[0]} (${c.author?.login || '未知'})`) : ['- 无数据']).join('\n')}

## 合并的PR (${mergedPrs.length})
${(mergedPrs.length > 0 ? mergedPrs.map(pr => `- #${pr.number} ${pr.title} (${pr.user?.login})`) : ['- 本周无合并PR']).join('\n')}

## 关闭的 Issue (${closedIssues.length})
${(closedIssues.length > 0 ? closedIssues.map(issue => `- #${issue.number} ${issue.title}`) : ['- 本周无关闭Issue']).join('\n')}

## 格式
用叙述风格生成周报:
1. **本周亮点** (本周最重要的2-3个成果)
2. **代码变更** (主要工作领域)
3. **问题修复** (修复的bug和应对的挑战)
4. **下周展望** (下周需要关注的方向)

简洁明了，使用Markdown格式。`;

return [{
  prompt: prompt,
  repo: config.repo,
  language: language,
  weekStart: dates.weekStart,
  weekEnd: dates.weekEnd
}];

const response = $json;
const content = response.content?.[0]?.text || response.content || 'Summary generation failed.';

return [{
  summary: content,
  repo: $node['Format Claude Prompt'].json.repo,
  weekStart: $node['Format Claude Prompt'].json.weekStart,
  weekEnd: $node['Format Claude Prompt'].json.weekEnd,
  generatedAt: new Date().toISOString()
}];
